//! Formats an `f32` exactly like C++ `std::ostream << float` with default
//! flags, i.e. `printf("%g", value)`: 6 significant digits, trailing zeros
//! stripped, fixed notation unless the decimal exponent is < -4 or >= 6.
//!
//! The value is first expanded to its exact decimal representation (every
//! `f32` is a dyadic rational `m * 2^e`), then rounded to 6 significant
//! digits using round-half-even on exact ties, matching glibc.

const PRECISION: usize = 6;

pub fn format_float(value: f32) -> String {
    if value == 0.0 {
        return if value.is_sign_negative() {
            "-0".to_string()
        } else {
            "0".to_string()
        };
    }

    let (negative, digits, exp10) = exact_decimal(value);
    let (digits, exp10) = round_significant(digits, exp10, PRECISION);

    let mut out = String::new();
    if negative {
        out.push('-');
    }

    if exp10 < -4 || exp10 >= PRECISION as i32 {
        // Scientific notation: d[.ddd]e±XX (exponent at least two digits).
        push_digits(&mut out, &digits[..1]);
        if digits.len() > 1 {
            out.push('.');
            push_digits(&mut out, &digits[1..]);
        }
        out.push('e');
        out.push(if exp10 < 0 { '-' } else { '+' });
        let abs = exp10.unsigned_abs();
        if abs < 10 {
            out.push('0');
        }
        out.push_str(&abs.to_string());
    } else if exp10 >= 0 {
        // Fixed notation with an integral part.
        let int_len = exp10 as usize + 1;
        for i in 0..int_len {
            out.push(if i < digits.len() {
                (b'0' + digits[i]) as char
            } else {
                '0'
            });
        }
        if digits.len() > int_len {
            out.push('.');
            push_digits(&mut out, &digits[int_len..]);
        }
    } else {
        // Fixed notation below 1: 0.00ddd
        out.push_str("0.");
        for _ in 0..(-exp10 - 1) {
            out.push('0');
        }
        push_digits(&mut out, &digits);
    }

    out
}

fn push_digits(out: &mut String, digits: &[u8]) {
    for &d in digits {
        out.push((b'0' + d) as char);
    }
}

/// Exact decimal expansion of `value`: returns (negative, significant
/// digits without leading zeros, exponent of the leading digit), such that
/// `value = ±0.digits * 10^(exp10 + 1)`.
fn exact_decimal(value: f32) -> (bool, Vec<u8>, i32) {
    let bits = value.to_bits();
    let negative = bits >> 31 != 0;
    let raw_exp = ((bits >> 23) & 0xff) as i32;
    let raw_frac = bits & 0x007f_ffff;

    // value = m * 2^e with integer m.
    let (mut m, mut e) = if raw_exp == 0 {
        (raw_frac, -126 - 23) // subnormal
    } else {
        (raw_frac | 0x0080_0000, raw_exp - 127 - 23)
    };
    while m & 1 == 0 {
        m >>= 1;
        e += 1;
    }

    if e >= 0 {
        let s = ((m as u128) << e).to_string();
        let exp10 = s.len() as i32 - 1;
        (negative, s.bytes().map(|b| b - b'0').collect(), exp10)
    } else {
        // value = m * 5^k / 10^k with k = -e; m is odd so the product
        // ends in 5 and never carries trailing zeros.
        let k = (-e) as usize;
        let mut digits: Vec<u8> = m.to_string().bytes().map(|b| b - b'0').collect();
        for _ in 0..k {
            mul_small(&mut digits, 5);
        }
        let exp10 = digits.len() as i32 - 1 - k as i32;
        (negative, digits, exp10)
    }
}

/// Multiplies a big decimal number (most significant digit first) by a
/// small factor in place.
fn mul_small(digits: &mut Vec<u8>, factor: u32) {
    let mut carry = 0u32;
    for d in digits.iter_mut().rev() {
        let v = (*d as u32) * factor + carry;
        *d = (v % 10) as u8;
        carry = v / 10;
    }
    while carry > 0 {
        digits.insert(0, (carry % 10) as u8);
        carry /= 10;
    }
}

/// Rounds the exact digit string to `precision` significant digits using
/// round-half-even, then strips trailing zeros. Returns the new digits and
/// the (possibly incremented) exponent of the leading digit.
fn round_significant(
    mut digits: Vec<u8>,
    mut exp10: i32,
    precision: usize,
) -> (Vec<u8>, i32) {
    if digits.len() > precision {
        let first_extra = digits[precision];
        let rest_nonzero = digits[precision + 1..].iter().any(|&d| d != 0);
        let round_up = first_extra > 5
            || (first_extra == 5 && (rest_nonzero || digits[precision - 1] % 2 == 1));
        digits.truncate(precision);
        if round_up {
            let mut i = digits.len();
            loop {
                if i == 0 {
                    digits.insert(0, 1);
                    exp10 += 1;
                    break;
                }
                i -= 1;
                if digits[i] == 9 {
                    digits[i] = 0;
                } else {
                    digits[i] += 1;
                    break;
                }
            }
        }
        while digits.len() > 1 && *digits.last().unwrap() == 0 {
            digits.pop();
        }
    }
    (digits, exp10)
}

